import React, { useState } from 'react';
import axios from 'axios';

// props විදිහට handleLoginSubmit සහ setCurrentPage ලබා ගන්න
const Login = ({ setShowLoginModal, handleLoginSubmit, setCurrentPage }) => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');

    const handleLogin = async (e) => {
        e.preventDefault();
        try {
            const response = await axios.post('http://localhost:8081/login', { username, password });
            
            if (response.data.status === "Success") {
                // සර්වර් එකෙන් ඩේටා ඇවිල්ලා සාර්ථක නම්...
                handleLoginSubmit(username, password); 
                // මෙතනින් කෙලින්ම ඩෑෂ්බෝඩ් එකට යවනවා
                setShowLoginModal(false);
            } else {
                setError(response.data.message);
            }
        } catch (err) {
            setError("Cannot connect to server!");
        }
    };

    return (
        <div style={{ padding: '20px', background: '#fff', textAlign: 'center' }}>
            <h2>Login</h2>
            {error && <p style={{ color: 'red' }}>{error}</p>}
            <form onSubmit={handleLogin}>
                <input type="text" placeholder="Username" onChange={(e) => setUsername(e.target.value)} /><br/>
                <input type="password" placeholder="Password" onChange={(e) => setPassword(e.target.value)} /><br/>
                <button type="submit">Login</button>
            </form>
        </div>
    );
};

export default Login;
